import hashlib, subprocess, shutil, os
LEAN = 'def eventual (x : Nat → Prop) := ∃ H, ∀ h, H ≤ h → x h\ndef gate (a b j : Nat) (p q : Nat → Prop) (h : Nat) :=\n (∀ u, u+a+b+1 ≤ h → p u) ∧\n (∀ g, g+a+1 ≤ h → q g ∨ ∀ f, j ≤ f → f < g → ¬ q f)\ndef dd (a b : Nat) (S : Nat → Prop) (h : Nat) := ¬ S h ∧ h < a+b+1\ndef cd (a b : Nat) (S : Nat → Prop) (h : Nat) := S h ∨ h < a+b+1\n\ntheorem traces (a b j h : Nat) (S : Nat → Prop) :\n ((¬ S h ∧ gate a b j (fun _ => False) (fun _ => False) h) ↔ dd a b S h) ∧\n ((S h ∨ gate a b j (fun _ => False) (fun _ => False) h) ↔ cd a b S h) := by\n have G : gate a b j (fun _ => False) (fun _ => False) h ↔ h < a+b+1 := by\n  constructor\n  · intro ⟨hp,_⟩; apply Classical.byContradiction; intro hn; exact hp 0 (by omega)\n  · intro hh; exact ⟨(fun u uh => by omega),fun _ _ => Or.inr (fun _ _ _ => id)⟩\n simp only [dd,cd,G,and_self]\n\ntheorem db_no_self (a b j : Nat) (hj : j ≤ a+b) (S x : Nat → Prop)\n (eqn : ∀ h, x h ↔ ¬ S h ∧ gate a b j x (dd a b S) h) : ¬ eventual x := by\n classical\n intro ⟨H,hH⟩\n have noS : ∀ s, ¬ S s := by\n  intro s ss\n  have nx : ¬ x s := fun xs => (eqn s).1 xs |>.1 ss\n  exact nx (((eqn (H+s+a+b+1)).1 (hH _ (by omega))).2.1 s (by omega))\n have dJ : dd a b S j := ⟨noS j,by omega⟩\n have nd : ¬ dd a b S (a+b+1) := fun d => by have := d.2; omega\n rcases ((eqn (H+(a+b+1)+a+1)).1 (hH _ (by omega))).2.2 (a+b+1) (by omega) with d | rest\n · exact nd d\n · exact rest j (by omega) (by omega) dJ\n\ntheorem cb_self (a b j : Nat) (hj : j ≤ a+b) (S x : Nat → Prop)\n (eqn : ∀ h, x h ↔ S h ∨ gate a b j x (cd a b S) h) : eventual x ↔ eventual S := by\n classical\n constructor\n · intro ⟨H,hH⟩\n   by_cases allS : ∀ g, a+b+1 ≤ g → S g\n   · exact ⟨a+b+1,allS⟩\n   · obtain ⟨g,ng⟩ := Classical.not_forall.mp allS\n     have gg : a+b+1 ≤ g := by apply Classical.byContradiction; intro hn; exact ng (fun h => False.elim (by omega))\n     have ns : ¬ S g := fun sg => ng (fun _ => sg)\n     refine ⟨H+g+a+1,?_⟩\n     intro h hh\n     rcases (eqn h).1 (hH h (by omega)) with sh | gateh\n     · exact sh\n     · rcases gateh.2 g (by omega) with dg | rest\n       · rcases dg with sg | small\n         · exact False.elim (ns sg)\n         · omega\n       · exact False.elim (rest j (by omega) (by omega) (Or.inr (by omega)))\n · intro ⟨H,hH⟩; exact ⟨H,fun h hh => (eqn h).2 (Or.inl (hH h hh))⟩\n\ntheorem db_safe (a b j : Nat) (S p q x : Nat → Prop)\n (eqn : ∀ h, x h ↔ ¬ S h ∧ gate a b j p q h)\n (pd : eventual (fun h => ¬ p h)) : eventual (fun h => ¬ x h) := by\n obtain ⟨H,hH⟩ := pd\n exact ⟨H+a+b+1,fun h hh xh => hH H (by omega) (((eqn h).1 xh).2.1 H (by omega))⟩\n\ntheorem cb_finite_safe (a b j M : Nat) (S p q x : Nat → Prop)\n (fin : ∀ h, M ≤ h → ¬ S h)\n (eqn : ∀ h, x h ↔ S h ∨ gate a b j p q h)\n (pd : eventual (fun h => ¬ p h)) : eventual (fun h => ¬ x h) := by\n obtain ⟨H,hH⟩ := pd\n refine ⟨M+H+a+b+1,fun h hh xh => ?_⟩\n rcases (eqn h).1 xh with sh | gh\n · exact fin h (by omega) sh\n · exact hH H (by omega) (gh.1 H (by omega))\n\ntheorem cb_cofinite_exploited (a b j : Nat) (S x : Nat → Prop)\n (cofin : eventual S)\n (eqn : ∀ h, x h ↔ S h ∨ gate a b j (fun _ => False) (fun _ => False) h) : eventual x := by\n obtain ⟨H,hH⟩ := cofin\n exact ⟨H,fun h hh => (eqn h).2 (Or.inl (hH h hh))⟩\n#print axioms traces\n#print axioms db_no_self\n#print axioms cb_self\n#print axioms db_safe\n#print axioms cb_finite_safe\n#print axioms cb_cofinite_exploited\n'
assert hashlib.sha256(LEAN.encode()).hexdigest() == '598813b525e79d1bcd00740c7436e03c6f006f5e77a12dfa7597a77c7df7fad3'
binary = next((p for p in (shutil.which('lean'), '/opt/elan/bin/lean', os.path.expanduser('~/.elan/bin/lean')) if p and os.path.exists(p)), None)
assert binary, 'Lean missing'
r = subprocess.run([binary, '--stdin'], input=LEAN, text=True, capture_output=True, timeout=90)
assert r.returncode == 0, r.stdout+r.stderr
assert 'sorryAx' not in r.stdout and r.stdout.count('axioms') == 6
for old,new in [('j ≤ a+b)', 'j ≤ a+b+1)'), ('¬ eventual x := by', 'eventual x := by'), ('eventual x ↔ eventual S', 'eventual x ↔ eventual (fun h => ¬ S h)')]:
    bad=LEAN.replace(old,new)
    assert bad != LEAN
    r=subprocess.run([binary,'--stdin'],input=bad,text=True,capture_output=True,timeout=15)
    assert r.returncode != 0, 'negative control accepted'
print('PASS: six Lean theorems, three mutations rejected')
